     "p": "XX",
     "c": "Bratislava",
     "u": "https://spectator.sme.sk/business/c/slovakia-could-lose-quarter-vineyards-drought-disease?utm_source=rss&utm_medium=feed&utm_campaign=spectator-rss",
     "angolo": "",
     "atlas": "Slovakia",
     "t": "2026-10-13T12:08+02:00"
